result.text:
        t.pendingCount > 0
          ? `Tienes ${fmtEUR(t.pending)} pendientes de pago`
          : "Todo al día. Nada pendiente de pago.";
      return {
        title: "Resumen",
        sub: `${who} · ${pending}`,
      };
    }
  }
}

